    def generate_news(self,category: NewsCategory,market_state: Dict[str, Any],event_context: Optional[Dict] = None) -> NewsEvent:
        templates = self.news_templates.get(category, self.news_templates[NewsCategory.MARKET])
        template = random.choice(templates)
        
        headline = self._fill_template(template["headline"], market_state, event_context)
        content = self._generate_content(headline, category, market_state)
        
        sentiment, sentiment_score = self.sentiment_analyzer.analyze(headline + " " + content)
        
        if template["positive"] and sentiment_score < 0:
            sentiment_score = abs(sentiment_score) * 0.5
        elif not template["positive"] and sentiment_score > 0:
            sentiment_score = -abs(sentiment_score) * 0.5
        
        if sentiment_score >= 0.7:
            sentiment = Sentiment.VERY_POSITIVE
        elif sentiment_score >= 0.2:
            sentiment = Sentiment.POSITIVE
        elif sentiment_score > -0.2:
            sentiment = Sentiment.NEUTRAL
        elif sentiment_score > -0.7:
            sentiment = Sentiment.NEGATIVE
        else:
            sentiment = Sentiment.VERY_NEGATIVE
        
        price_impact = sentiment_score * 0.05 
        volume_impact = abs(sentiment_score) * 0.3
        return NewsEvent(event_id=f"news_{datetime.now().timestamp()}",category=category,headline=headline,content=content,sentiment=sentiment,sentiment_score=sentiment_score,timestamp=datetime.now(),relevance_score=random.uniform(0.5, 1.0),impact_duration=random.randint(3, 10),price_impact_estimate=price_impact,volume_impact_estimate=volume_impact)

    
